/**
 * Mock Deployment Orchestrator Server
 * 
 * This is a simple Express server that simulates a deployment orchestrator.
 * It receives deployment configurations and logs them for audit purposes.
 * 
 * Usage: node orchestrator-mock.js
 * Server will run on http://localhost:3003
 */

const http = require('http');
const url = require('url');
const fs = require('fs');
const path = require('path');

const PORT = 3003;
const AUDIT_LOG_DIR = './audit-logs';

// Create audit logs directory if it doesn't exist
if (!fs.existsSync(AUDIT_LOG_DIR)) {
    fs.mkdirSync(AUDIT_LOG_DIR, { recursive: true });
}

// Create HTTP server
const server = http.createServer((req, res) => {
    const parsedUrl = url.parse(req.url, true);

    // Set CORS headers
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
    res.setHeader('Content-Type', 'application/json');

    // Handle preflight requests
    if (req.method === 'OPTIONS') {
        res.writeHead(200);
        res.end();
        return;
    }

    // Handle deploy-config POST request
    if (req.method === 'POST' && parsedUrl.pathname === '/api/deploy-config') {
        let body = '';

        req.on('data', chunk => {
            body += chunk.toString();
        });

        req.on('end', () => {
            try {
                const config = JSON.parse(body);

                // Log configuration to audit log file
                const timestamp = new Date().toISOString();
                const logEntry = {
                    timestamp,
                    received_at: new Date().toLocaleString(),
                    deployment_config: config,
                    request_ip: req.connection.remoteAddress
                };

                // Write to audit log
                const logFilename = `deploy_${config.timestamp}_${Date.now()}.json`;
                const logPath = path.join(AUDIT_LOG_DIR, logFilename);

                fs.writeFileSync(logPath, JSON.stringify(logEntry, null, 2));

                console.log(`\n${new Date().toLocaleString()} - Received deployment config`);
                console.log(`  Project: ${config.project}`);
                console.log(`  Variables: ${config.variable_count}`);
                console.log(`  Logged to: ${logFilename}`);

                // Send success response
                const response = {
                    success: true,
                    message: 'Configuration received and logged',
                    deployment_id: logFilename.replace('.json', ''),
                    variables_registered: config.variable_count,
                    audit_log: logPath
                };

                res.writeHead(200);
                res.end(JSON.stringify(response, null, 2));

            } catch (error) {
                console.error(`Error parsing JSON: ${error.message}`);
                res.writeHead(400);
                res.end(JSON.stringify({
                    success: false,
                    error: 'Invalid JSON payload',
                    details: error.message
                }, null, 2));
            }
        });

        return;
    }

    // Handle audit logs listing
    if (req.method === 'GET' && parsedUrl.pathname === '/api/audit-logs') {
        try {
            const files = fs.readdirSync(AUDIT_LOG_DIR)
                .filter(f => f.endsWith('.json'))
                .sort()
                .reverse();

            const logs = files.map(filename => {
                const filepath = path.join(AUDIT_LOG_DIR, filename);
                const content = JSON.parse(fs.readFileSync(filepath, 'utf8'));
                return {
                    filename,
                    timestamp: content.timestamp,
                    project: content.deployment_config.project,
                    variables: content.deployment_config.variable_count,
                    ip: content.request_ip
                };
            });

            res.writeHead(200);
            res.end(JSON.stringify({
                total_logs: logs.length,
                logs
            }, null, 2));
        } catch (error) {
            res.writeHead(500);
            res.end(JSON.stringify({
                error: 'Failed to read audit logs',
                details: error.message
            }, null, 2));
        }
        return;
    }

    // Handle audit log details
    if (req.method === 'GET' && parsedUrl.pathname.startsWith('/api/audit-logs/')) {
        const filename = parsedUrl.pathname.replace('/api/audit-logs/', '');
        const filepath = path.join(AUDIT_LOG_DIR, filename + '.json');

        try {
            if (!fs.existsSync(filepath)) {
                res.writeHead(404);
                res.end(JSON.stringify({
                    error: 'Log file not found'
                }, null, 2));
                return;
            }

            const content = JSON.parse(fs.readFileSync(filepath, 'utf8'));
            res.writeHead(200);
            res.end(JSON.stringify(content, null, 2));
        } catch (error) {
            res.writeHead(500);
            res.end(JSON.stringify({
                error: 'Failed to read log file',
                details: error.message
            }, null, 2));
        }
        return;
    }

    // Handle root/health check
    if (req.method === 'GET' && parsedUrl.pathname === '/') {
        res.writeHead(200);
        res.end(JSON.stringify({
            service: 'Deployment Orchestrator Mock',
            status: 'running',
            version: '1.0.0',
            endpoints: {
                'POST /api/deploy-config': 'Submit deployment configuration',
                'GET /api/audit-logs': 'List all audit logs',
                'GET /api/audit-logs/:id': 'Get specific audit log'
            }
        }, null, 2));
        return;
    }

    // 404 Not Found
    res.writeHead(404);
    res.end(JSON.stringify({
        error: 'Endpoint not found',
        path: parsedUrl.pathname
    }, null, 2));
});

server.listen(PORT, () => {
    console.log(`\n========================================`);
    console.log(`Deployment Orchestrator Mock Server`);
    console.log(`========================================`);
    console.log(`Server running on http://localhost:${PORT}`);
    console.log(`Audit logs directory: ${AUDIT_LOG_DIR}`);
    console.log(``);
    console.log(`Endpoints:`);
    console.log(`  POST /api/deploy-config    - Submit deployment config`);
    console.log(`  GET  /api/audit-logs       - List all audit logs`);
    console.log(`  GET  /api/audit-logs/:id   - View specific audit log`);
    console.log(`  GET  /                     - Health check`);
    console.log(``);
    console.log(`Press Ctrl+C to stop the server\n`);
});

server.on('error', (err) => {
    if (err.code === 'EADDRINUSE') {
        console.error(`Port ${PORT} is already in use. Please stop the existing server or use a different port.`);
    } else {
        console.error(`Server error: ${err.message}`);
    }
    process.exit(1);
});

