/**
 * Mock Deployment Orchestrator Service
 * Listens on http://localhost:3003/api/deploy-config
 * For testing and audit compliance verification
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 3003;
const AUDIT_LOG_FILE = 'deploy-audit.log';

// Helper to log to both console and file
function logAudit(message) {
    const timestamp = new Date().toISOString();
    const logEntry = `[${timestamp}] ${message}\n`;
    console.log(logEntry.trim());
    fs.appendFileSync(AUDIT_LOG_FILE, logEntry);
}

// Request handler
const server = http.createServer((req, res) => {
    // Enable CORS
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, User-Agent');
    res.setHeader('Content-Type', 'application/json');

    // Handle OPTIONS for CORS
    if (req.method === 'OPTIONS') {
        res.writeHead(200);
        res.end();
        return;
    }

    // Handle POST to /api/deploy-config
    if (req.method === 'POST' && req.url === '/api/deploy-config') {
        let body = '';

        req.on('data', (chunk) => {
            body += chunk.toString();
        });

        req.on('end', () => {
            try {
                const config = JSON.parse(body);

                // Log the deployment config
                logAudit(`✓ DEPLOY CONFIG RECEIVED from project: ${config.project}`);
                logAudit(`  Timestamp: ${config.timestamp}`);
                logAudit(`  Variables: ${Object.keys(config.environment).length}`);

                // Log sensitive data masking
                const envKeys = Object.keys(config.environment);
                logAudit(`  Configuration keys: ${envKeys.join(', ')}`);

                // Validate config structure
                if (!config.project || !config.timestamp || !config.environment) {
                    throw new Error('Invalid config structure');
                }

                // Generate audit record
                const auditRecord = {
                    status: 'ACCEPTED',
                    project: config.project,
                    timestamp: config.timestamp,
                    receivedAt: new Date().toISOString(),
                    variableCount: Object.keys(config.environment).length,
                    deploymentId: `DEPLOY-${Date.now()}`
                };

                logAudit(`  Deployment ID: ${auditRecord.deploymentId}`);
                logAudit(`  Status: ${auditRecord.status}`);

                // Save full audit record
                const auditRecordPath = path.join('deploy-records', `${auditRecord.deploymentId}.json`);
                if (!fs.existsSync('deploy-records')) {
                    fs.mkdirSync('deploy-records', { recursive: true });
                }
                fs.writeFileSync(auditRecordPath, JSON.stringify(auditRecord, null, 2));

                // Return success response
                res.writeHead(202, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({
                    status: 'accepted',
                    message: 'Configuration accepted for deployment',
                    deploymentId: auditRecord.deploymentId,
                    timestamp: auditRecord.receivedAt
                }));

            } catch (error) {
                logAudit(`✗ ERROR: Failed to process config - ${error.message}`);
                res.writeHead(400, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({
                    status: 'error',
                    message: 'Invalid configuration format',
                    error: error.message
                }));
            }
        });

    } else if (req.method === 'GET' && req.url === '/health') {
        // Health check endpoint
        res.writeHead(200);
        res.end(JSON.stringify({ status: 'ok', service: 'mock-orchestrator' }));

    } else {
        res.writeHead(404);
        res.end(JSON.stringify({ error: 'Not found' }));
    }
});

// Start server
server.listen(PORT, 'localhost', () => {
    const timestamp = new Date().toISOString();
    console.log(`\n${'='.repeat(50)}`);
    console.log('Mock Deployment Orchestrator');
    console.log(`${'='.repeat(50)}`);
    console.log(`Started at ${timestamp}`);
    console.log(`Listening on http://localhost:${PORT}`);
    console.log(`API Endpoint: http://localhost:${PORT}/api/deploy-config`);
    console.log(`Health Check: http://localhost:${PORT}/health`);
    console.log(`Audit Log: ${AUDIT_LOG_FILE}`);
    console.log(`${'='.repeat(50)}\n`);

    logAudit('Mock Orchestrator Service Started');
});

// Graceful shutdown
process.on('SIGINT', () => {
    logAudit('Mock Orchestrator Service Stopped');
    server.close(() => {
        console.log('\nServer closed');
        process.exit(0);
    });
});

