#!/usr/bin/env node

/**
 * Mock Deployment Orchestrator Server
 * Runs on http://localhost:3003
 * Logs received deployment configurations for audit compliance
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 3003;
const LOG_DIR = './deploy-logs';
const CONFIG_ENDPOINT = '/api/deploy-config';

// Ensure log directory exists
if (!fs.existsSync(LOG_DIR)) {
    fs.mkdirSync(LOG_DIR, { recursive: true });
    console.log(`Created log directory: ${LOG_DIR}`);
}

// Create HTTP server
const server = http.createServer((req, res) => {
    // Enable CORS
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
    res.setHeader('Content-Type', 'application/json');

    // Handle OPTIONS requests
    if (req.method === 'OPTIONS') {
        res.writeHead(200);
        res.end();
        return;
    }

    // Handle deployment config POST
    if (req.method === 'POST' && req.url === CONFIG_ENDPOINT) {
        let body = '';

        req.on('data', chunk => {
            body += chunk.toString();
        });

        req.on('end', () => {
            try {
                // Parse and validate JSON
                const config = JSON.parse(body);

                // Validate structure
                if (!config.timestamp || !config.config) {
                    res.writeHead(400);
                    res.end(JSON.stringify({
                        status: 'error',
                        message: 'Invalid payload structure. Expected {timestamp, config}'
                    }));
                    return;
                }

                // Log configuration to file for audit
                const timestamp = new Date().toISOString();
                const logFile = path.join(LOG_DIR, `deploy-${new Date().toISOString().split('T')[0]}.jsonl`);
                const auditEntry = {
                    received_at: timestamp,
                    source_timestamp: config.timestamp,
                    config_count: Object.keys(config.config).length,
                    variables: Object.keys(config.config).sort()
                };

                // Append to log file (JSONL format for audit trail)
                fs.appendFileSync(logFile, JSON.stringify(auditEntry) + '\n');

                // Also write detailed config to timestamped file
                const detailFile = path.join(LOG_DIR, `config-${config.timestamp.replace(/[:.]/g, '-')}.json`);
                fs.writeFileSync(detailFile, JSON.stringify(config, null, 2));

                console.log(`[${timestamp}] Config received with ${Object.keys(config.config).length} variables`);
                console.log(`  Variables: ${Object.keys(config.config).join(', ')}`);
                console.log(`  Logged to: ${logFile}`);

                // Return success response
                res.writeHead(200);
                res.end(JSON.stringify({
                    status: 'success',
                    message: 'Configuration received and logged for audit',
                    audit_id: config.timestamp,
                    variables_count: Object.keys(config.config).length,
                    log_file: logFile
                }));

            } catch (error) {
                console.error('Error processing config:', error.message);
                res.writeHead(400);
                res.end(JSON.stringify({
                    status: 'error',
                    message: 'Invalid JSON payload: ' + error.message
                }));
            }
        });

        return;
    }

    // Handle health check
    if (req.method === 'GET' && req.url === '/health') {
        res.writeHead(200);
        res.end(JSON.stringify({
            status: 'healthy',
            service: 'deployment-orchestrator',
            endpoint: CONFIG_ENDPOINT
        }));
        return;
    }

    // Handle audit logs retrieval
    if (req.method === 'GET' && req.url === '/logs') {
        try {
            const files = fs.readdirSync(LOG_DIR);
            const logs = files.map(file => ({
                name: file,
                path: path.join(LOG_DIR, file),
                size: fs.statSync(path.join(LOG_DIR, file)).size
            }));

            res.writeHead(200);
            res.end(JSON.stringify({
                status: 'success',
                logs: logs
            }));
        } catch (error) {
            res.writeHead(500);
            res.end(JSON.stringify({
                status: 'error',
                message: error.message
            }));
        }
        return;
    }

    // 404 for unknown endpoints
    res.writeHead(404);
    res.end(JSON.stringify({
        status: 'error',
        message: 'Not found',
        available_endpoints: {
            'POST /api/deploy-config': 'Submit deployment config',
            'GET /health': 'Health check',
            'GET /logs': 'List audit logs'
        }
    }));
});

// Start server
server.listen(PORT, () => {
    console.log(`\n${'='.repeat(60)}`);
    console.log(`  Deployment Orchestrator Mock Server`);
    console.log(`${'='.repeat(60)}`);
    console.log(`  Server listening on: http://localhost:${PORT}`);
    console.log(`  Config endpoint: ${CONFIG_ENDPOINT}`);
    console.log(`  Audit logs directory: ${LOG_DIR}`);
    console.log(`\n  Available endpoints:`);
    console.log(`    POST ${CONFIG_ENDPOINT}  - Submit deployment config`);
    console.log(`    GET  /health           - Health check`);
    console.log(`    GET  /logs             - List audit logs`);
    console.log(`${'='.repeat(60)}\n`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
    console.log('\nShutting down orchestrator...');
    server.close(() => {
        console.log('Server closed');
        process.exit(0);
    });
});

