#!/usr/bin/env node

/**
 * Mock Deployment Orchestrator Server
 * 
 * This is a simple Node.js HTTP server that mimics a deployment orchestrator.
 * It receives deployment configurations from deploy.sh and stores them for audit compliance.
 * 
 * Usage: node mock-orchestrator.js [port]
 * Default port: 3003
 */

const http = require('http');
const url = require('url');
const fs = require('fs');
const path = require('path');

// Configuration
const PORT = process.argv[2] || 3003;
const AUDIT_LOG_DIR = path.join(__dirname, 'audit-logs');
const AUDIT_LOG_FILE = path.join(AUDIT_LOG_DIR, 'deployments.jsonl');

// Ensure audit log directory exists
if (!fs.existsSync(AUDIT_LOG_DIR)) {
    fs.mkdirSync(AUDIT_LOG_DIR, { recursive: true });
    console.log(`✓ Created audit log directory: ${AUDIT_LOG_DIR}`);
}

// Create server
const server = http.createServer((req, res) => {
    const parsedUrl = url.parse(req.url, true);
    const pathname = parsedUrl.pathname;

    // CORS headers
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, User-Agent');
    res.setHeader('Content-Type', 'application/json');

    // Handle OPTIONS requests
    if (req.method === 'OPTIONS') {
        res.writeHead(200);
        res.end();
        return;
    }

    // Health check endpoint
    if (pathname === '/api/health') {
        if (req.method === 'GET') {
            res.writeHead(200);
            res.end(JSON.stringify({
                status: 'ok',
                service: 'deployment-orchestrator',
                timestamp: new Date().toISOString(),
                port: PORT
            }, null, 2));
            return;
        }
    }

    // Deploy config endpoint (main endpoint)
    if (pathname === '/api/deploy-config') {
        if (req.method === 'POST') {
            let body = '';

            req.on('data', chunk => {
                body += chunk.toString();
            });

            req.on('end', () => {
                try {
                    // Parse JSON payload
                    const config = JSON.parse(body);

                    // Validate required fields
                    const requiredFields = ['timestamp', 'project', 'variables', 'user', 'hostname'];
                    const missingFields = requiredFields.filter(field => !(field in config));

                    if (missingFields.length > 0) {
                        res.writeHead(400);
                        res.end(JSON.stringify({
                            success: false,
                            error: 'Missing required fields',
                            missing: missingFields
                        }, null, 2));
                        return;
                    }

                    // Add receipt timestamp
                    config.received_at = new Date().toISOString();
                    config.receipt_id = generateReceiptId();

                    // Log to audit file (JSONL format - one JSON object per line)
                    const auditEntry = {
                        receipt_id: config.receipt_id,
                        timestamp: config.timestamp,
                        received_at: config.received_at,
                        project: config.project,
                        git_branch: config.git_branch,
                        git_commit: config.git_commit,
                        user: config.user,
                        hostname: config.hostname,
                        variables_count: Object.keys(config.variables).length,
                        variables_list: Object.keys(config.variables)
                    };

                    fs.appendFileSync(
                        AUDIT_LOG_FILE,
                        JSON.stringify(auditEntry) + '\n'
                    );

                    // Log to console
                    console.log(`\n${new Date().toISOString()} [DEPLOY-CONFIG] Receipt: ${config.receipt_id}`);
                    console.log(`  Project: ${config.project}`);
                    console.log(`  Branch: ${config.git_branch}`);
                    console.log(`  Commit: ${config.git_commit}`);
                    console.log(`  User: ${config.user}@${config.hostname}`);
                    console.log(`  Variables: ${Object.keys(config.variables).length}`);
                    console.log(`  Audit logged to: ${AUDIT_LOG_FILE}`);

                    // Send success response
                    res.writeHead(201);
                    res.end(JSON.stringify({
                        success: true,
                        message: 'Configuration received and logged for audit compliance',
                        receipt_id: config.receipt_id,
                        timestamp: config.received_at,
                        variables_received: Object.keys(config.variables).length
                    }, null, 2));

                } catch (error) {
                    console.error(`[ERROR] Failed to parse JSON:`, error.message);
                    res.writeHead(400);
                    res.end(JSON.stringify({
                        success: false,
                        error: 'Invalid JSON payload',
                        details: error.message
                    }, null, 2));
                }
            });

            return;
        }
    }

    // Audit logs endpoint (retrieve logs)
    if (pathname === '/api/audit-logs') {
        if (req.method === 'GET') {
            try {
                const logs = fs.readFileSync(AUDIT_LOG_FILE, 'utf8')
                    .split('\n')
                    .filter(line => line.trim())
                    .map(line => JSON.parse(line));

                res.writeHead(200);
                res.end(JSON.stringify({
                    count: logs.length,
                    logs: logs
                }, null, 2));
                return;
            } catch (error) {
                res.writeHead(200);
                res.end(JSON.stringify({
                    count: 0,
                    logs: [],
                    message: 'No audit logs found'
                }, null, 2));
            }
        }
    }

    // Status endpoint
    if (pathname === '/api/status') {
        if (req.method === 'GET') {
            try {
                const logCount = fs.readFileSync(AUDIT_LOG_FILE, 'utf8')
                    .split('\n')
                    .filter(line => line.trim())
                    .length;

                res.writeHead(200);
                res.end(JSON.stringify({
                    status: 'healthy',
                    service: 'deployment-orchestrator',
                    port: PORT,
                    audit_logs_file: AUDIT_LOG_FILE,
                    audit_logs_count: logCount,
                    uptime_seconds: process.uptime()
                }, null, 2));
            } catch (error) {
                res.writeHead(200);
                res.end(JSON.stringify({
                    status: 'healthy',
                    service: 'deployment-orchestrator',
                    port: PORT,
                    audit_logs_count: 0,
                    uptime_seconds: process.uptime()
                }, null, 2));
            }
            return;
        }
    }

    // Root endpoint
    if (pathname === '/') {
        res.writeHead(200);
        res.end(JSON.stringify({
            service: 'Deployment Orchestrator',
            version: '1.0',
            endpoints: {
                '/api/health': 'GET - Health check',
                '/api/deploy-config': 'POST - Submit deployment configuration',
                '/api/audit-logs': 'GET - Retrieve audit logs',
                '/api/status': 'GET - Service status',
                '/': 'GET - This help message'
            }
        }, null, 2));
        return;
    }

    // 404 Not Found
    res.writeHead(404);
    res.end(JSON.stringify({
        error: 'Endpoint not found',
        path: pathname,
        method: req.method
    }, null, 2));
});

// Helper function to generate receipt ID
function generateReceiptId() {
    const timestamp = Date.now();
    const random = Math.random().toString(36).substring(2, 8).toUpperCase();
    return `RECEIPT-${timestamp}-${random}`;
}

// Start server
server.listen(PORT, '127.0.0.1', () => {
    console.log('\n' + '='.repeat(60));
    console.log('  🚀 Deployment Orchestrator Server Started');
    console.log('='.repeat(60));
    console.log(`  Address: http://127.0.0.1:${PORT}`);
    console.log(`  Audit Log: ${AUDIT_LOG_FILE}`);
    console.log('');
    console.log('  Available Endpoints:');
    console.log(`    GET  http://127.0.0.1:${PORT}/api/health`);
    console.log(`    GET  http://127.0.0.1:${PORT}/api/status`);
    console.log(`    POST http://127.0.0.1:${PORT}/api/deploy-config`);
    console.log(`    GET  http://127.0.0.1:${PORT}/api/audit-logs`);
    console.log('');
    console.log('  Press Ctrl+C to stop');
    console.log('='.repeat(60) + '\n');
});

// Handle graceful shutdown
process.on('SIGINT', () => {
    console.log('\n\n✓ Shutting down orchestrator server...');
    server.close(() => {
        console.log('✓ Server closed');
        process.exit(0);
    });
});

// Error handling
server.on('error', (error) => {
    console.error('Server error:', error);
    process.exit(1);
});

