#!/usr/bin/env node

/**
 * Mock Deployment Orchestrator
 * Listens on http://localhost:3003/api/deploy-config
 * Logs received deployment configurations for audit compliance
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 3003;
const AUDIT_LOG = path.join(__dirname, 'audit_log.json');

// Initialize audit log file if it doesn't exist
if (!fs.existsSync(AUDIT_LOG)) {
  fs.writeFileSync(AUDIT_LOG, '[]', 'utf-8');
}

const server = http.createServer((req, res) => {
  // Only handle POST requests to /api/deploy-config
  if (req.method !== 'POST' || req.url !== '/api/deploy-config') {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
    return;
  }

  let body = '';

  req.on('data', (chunk) => {
    body += chunk.toString();
  });

  req.on('end', () => {
    try {
      const payload = JSON.parse(body);

      // Create audit entry
      const auditEntry = {
        id: Date.now(),
        timestamp: new Date().toISOString(),
        project: payload.project,
        deploymentTimestamp: payload.timestamp,
        configKeys: Object.keys(payload.config),
        configCount: Object.keys(payload.config).length,
        status: 'received'
      };

      // Append to audit log
      const logs = JSON.parse(fs.readFileSync(AUDIT_LOG, 'utf-8'));
      logs.push(auditEntry);
      fs.writeFileSync(AUDIT_LOG, JSON.stringify(logs, null, 2), 'utf-8');

      // Log to console
      console.log(`\n📋 Deployment config received:`);
      console.log(`   Project: ${payload.project}`);
      console.log(`   Deployment ID: ${payload.timestamp}`);
      console.log(`   Config variables: ${auditEntry.configCount}`);
      console.log(`   Variables: ${auditEntry.configKeys.join(', ')}`);
      console.log(`   Logged to: ${AUDIT_LOG}`);

      // Send success response
      res.writeHead(202, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        status: 'accepted',
        message: 'Configuration received and logged for audit compliance',
        auditId: auditEntry.id
      }));
    } catch (error) {
      console.error('Error processing request:', error.message);
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ 
        error: 'Invalid JSON payload',
        details: error.message 
      }));
    }
  });
});

server.listen(PORT, () => {
  console.log(`\n🚀 Mock Deployment Orchestrator running on http://localhost:${PORT}`);
  console.log(`📌 Endpoint: POST /api/deploy-config`);
  console.log(`📝 Audit log: ${AUDIT_LOG}\n`);
});

// Handle graceful shutdown
process.on('SIGINT', () => {
  console.log('\n\n👋 Orchestrator shutting down...');
  server.close();
  process.exit(0);
});

