    console.log(`\n[${new Date().toISOString()}] ${req.method} ${req.url}`);

    // Enable CORS headers
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
    res.setHeader('Content-Type', 'application/json');

    // Handle OPTIONS preflight
    if (req.method === 'OPTIONS') {
        res.writeHead(200);
        res.end();
        return;
    }

    // Handle POST /api/deploy-config
    if (req.method === 'POST' && req.url === '/api/deploy-config') {
        let body = '';

        req.on('data', chunk => {
            body += chunk.toString();
        });

        req.on('end', () => {
            try {
                const payload = JSON.parse(body);

                console.log('Received deployment config:');
                console.log(`  Project: ${payload.project}`);
                console.log(`  Timestamp: ${payload.timestamp}`);
                console.log(`  Config variables: ${Object.keys(payload.config).length}`);

                // Log all config keys
                console.log('  Configuration:');
                Object.entries(payload.config).forEach(([key, value]) => {
                    // Mask sensitive values
                    const maskedValue = (key.toLowerCase().includes('password') || 
                                        key.toLowerCase().includes('secret') || 
                                        key.toLowerCase().includes('key')) 
                        ? '***MASKED***' 
                        : value;
                    console.log(`    - ${key}: ${maskedValue}`);
                });

                // Return success response
                const response = {
                    success: true,
                    message: 'Deployment config received and logged for audit',
                    configId: `deploy-${payload.timestamp}`,
                    receivedAt: new Date().toISOString(),
                    variableCount: Object.keys(payload.config).length
                };

                res.writeHead(200);
                res.end(JSON.stringify(response, null, 2));

            } catch (err) {
                console.error('Error parsing payload:', err.message);
                res.writeHead(400);
                res.end(JSON.stringify({
                    success: false,
                    error: 'Invalid JSON payload',
                    details: err.message
                }, null, 2));
            }
        });

        return;
    }

    // Handle 404
    res.writeHead(404);
    res.end(JSON.stringify({
        success: false,
        error: 'Endpoint not found',
        path: req.url,
        method: req.method
    }, null, 2));
